pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address oracleAddr) public {
        // restrict to contract addresses to pass internal check during init
        vm.assume(oracleAddr != address(0) && oracleAddr.code.length > 0);
        // need a minimal contract that exposes currentVersion/atVersion to satisfy UPayoffProvider
        OracleMock mock = new OracleMock();
        // fuzzed oracle address, but we must point to a valid contract, so use the mock
        // the fuzzer varies oracleAddr, we use it as an identifier: we record it in the productInfo
        // but the actual oracle stored is the mock (which is a contract). The property is that
        // oracle() returns the address we set (the mock), not a hardcoded address(0).
        // Since oracle() in reference returns the stored address and mutant returns address(0),
        // we just check that oracle() != address(0) when initialized with a valid contract.
        // To keep the property tight: assert that oracle() returns the address of the mock we passed.
        C.ProductInfo memory info = C.ProductInfo({
            name: "test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType(0),
                payoffDirection: PayoffDefinitionLib.PayoffDirection(0),
                data: bytes30(0)
            }),
            oracle: IOracleProvider(address(mock)),
            maintenance: UFixed18.wrap(1e17),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(type(uint256).max),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });
        // prank the controller (which is address(this) since C.initialize checks msg.sender is IController)
        // we need to implement IController minimally, but we can't. We'll deploy a minimal controller.
        // Simplified: we bypass by using a pre-deployed controller mock.
        // We'll instead directly test oracle() after initialization; the initialization is done in setUp with a mock controller.
        // This test assumes setUp initializes c with a known oracle. We'll adjust setUp to do this.
        // Actually, we can't initialize in setUp without a controller. So we must deploy a controller mock.
        // To keep it simple, we'll deploy a minimal controller that passes checks and allows initialization.
        // Then call oracle() and assert it's the mock address.
    }
}

// Minimal oracle that implements IOracleProvider
