pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address oracleAddr) public {
        // Oracle must be a contract address to pass initialization
        vm.assume(oracleAddr != address(0));
        vm.assume(oracleAddr.code.length > 0);

        // Use the oracle's own oracle() getter to avoid needing a real IOracleProvider implementation
        // We deploy a minimal contract that acts as an oracle and also returns itself
        OracleMock mockOracle = new OracleMock();

        // Re-bind to the fuzzed address - we cannot deploy at an arbitrary address,
        // so we use a different approach: we initialize C with a valid oracle address
        // whose oracle() getter will return itself (the address of the mock).
        // Since C.__UPayoffProvider__initialize stores the oracle via _oracle.store(),
        // we need to call initialize() on C properly. However, C's initialize requires
        // msg.sender to be the controller, so we deploy a minimal controller.
        ControllerMock mockController = new ControllerMock();
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "Test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType.PASSTHROUGH,
                payoffDirection: PayoffDefinitionLib.PayoffDirection.LONG,
                data: bytes30(0)
            }),
            oracle: IOracleProvider(address(mockOracle)),
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(0),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });
        vm.prank(address(mockController));
        c.initialize(info);

        // Now read oracle() and check that it matches the address we passed in
        // The reference returns the stored address (mockOracle), the mutant returns address(0)
        assertEq(address(c.oracle()), address(mockOracle), "oracle() must return the stored oracle address");
    }
}

contract OracleMock is IOracleProvider {
    function sync() external returns (OracleVersion memory) {
        return OracleVersion({ version: 0, timestamp: 0, price: Fixed18.wrap(0) });
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion({ version: 0, timestamp: 0, price: Fixed18.wrap(0) });
    }
    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion({ version: 0, timestamp: 0, price: Fixed18.wrap(0) });
    }
}

contract ControllerMock {
    function isProduct(IProduct) external pure returns (bool) { return true; }
    function owner() external view returns (address) { return address(this); }
    function coordinatorFor(IProduct) external pure returns (uint256) { return 0; }
