pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address oracleAddr, uint256 price) public {
        // Ensure the oracle address is a contract with code, otherwise initialization reverts.
        vm.assume(oracleAddr != address(0));
        vm.assume(oracleAddr.code.length > 0);

        // Deploy a minimal oracle that provides the required interface.
        MockOracle mockOracle = new MockOracle(int256(price));
        address mockAddr = address(mockOracle);

        // The fuzzer provides the address; we force it to use our mock to guarantee non-zero code.
        // The property is about the stored oracle, not the mock's correctness.
        C.IProduct.ProductInfo memory info = C.IProduct.ProductInfo({
            name: "",
            symbol: "",
            payoffDefinition: C.PayoffDefinition(
                C.PayoffDefinitionLib.PayoffType.PASSTHROUGH,
                C.PayoffDefinitionLib.PayoffDirection.LONG,
                bytes30(0)
            ),
            oracle: C.IOracleProvider(mockAddr),
            maintenance: C.UFixed18.wrap(1e18),
            fundingFee: C.UFixed18.wrap(0),
            makerFee: C.UFixed18.wrap(0),
            takerFee: C.UFixed18.wrap(0),
            positionFee: C.UFixed18.wrap(0),
            makerLimit: C.UFixed18.wrap(1000e18),
            utilizationCurve: C.JumpRateUtilizationCurve({
                minRate: C.PackedFixed18.wrap(0),
                maxRate: C.PackedFixed18.wrap(0),
                targetRate: C.PackedFixed18.wrap(0),
                targetUtilization: C.PackedUFixed18.wrap(0)
            })
        });

        vm.prank(address(this));
        c.initialize(info);

        // Assert that the oracle getter returns the address that was passed during initialization.
        assertTrue(address(c.oracle()) == mockAddr);
    }
}

contract MockOracle {
    int256 public price;
    constructor(int256 _price) { price = _price; }
    function sync() external returns (C.IOracleProvider.OracleVersion memory) {
        return C.IOracleProvider.OracleVersion(1, block.timestamp, C.Fixed18.wrap(price));
    }
    function currentVersion() external view returns (C.IOracleProvider.OracleVersion memory) {
        return C.IOracleProvider.OracleVersion(1, block.timestamp, C.Fixed18.wrap(price));
    }
    function atVersion(uint256) external view returns (C.IOracleProvider.OracleVersion memory) {
        return C.IOracleProvider.OracleVersion(1, block.timestamp, C.Fixed18.wrap(price));
    }
}

