pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes30 data, uint8 payoffType, uint8 payoffDirection) public {
        // Restrict payoffType and payoffDirection to valid enum ranges
        // PayoffType: 0=PASSTHROUGH, 1=... (assuming >=2 variants)
