contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(int256 rawPrice, uint256 timestamp) public {
        // Bound to valid oracle values
        bound(rawPrice, -1e30, 1e30);
        bound(timestamp, 1, type(uint64).max);
        vm.assume(rawPrice != 0);

        // Deploy a mock oracle that returns the fuzzed raw price
        MockOracle oracle = new MockOracle(rawPrice, timestamp);

        // Build a simple valid PayoffDefinition (payoffType = 1, direction = 0, no data)
        PayoffDefinition memory def = PayoffDefinition(PayoffDefinitionLib.PayoffType.wrap(1), PayoffDefinitionLib.PayoffDirection.wrap(0), bytes30(0));

        // We must call initialize; the controller must be the deployer. We use ourselves as controller.
        // Override the controller check: C expects controller to be a contract and to be the initializer.
        // Deploy a minimal controller that returns true for isProduct, etc.
        MockController controller = new MockController(oracle);

        // Build ProductInfo
        C.ProductInfo memory info = C.ProductInfo({
            name: "TEST",
            symbol: "TST",
            payoffDefinition: def,
            oracle: oracle,
            maintenance: UFixed18.wrap(1e16),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(type(uint256).max),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });

        // Initialize C via the controller address
        vm.prank(address(controller));
        c.initialize(info);

        // Now read currentVersion
        IOracleProvider.OracleVersion memory v = c.currentVersion();

        // The invariant: the price returned MUST be transformed by the payoffDefinition.
        // PayoffType(1) is PASSTHROUGH? Actually the enum values depend on library.
        // For a generic valid payoff we just check that it DIFFERS from raw price or equals transformed.
        // We know the mock oracle returns rawPrice. The transformed price is def.transform(Fixed18.wrap(rawPrice)).
        // We cannot call the library directly, but we can compute what it should be.
        // Since C is the only contract we can observe, we read payoffDefinition from C.
        PayoffDefinition memory storedDef = c.payoffDefinition();
        // Compute expected transform
        Fixed18 expected = storedDef.transform(Fixed18.wrap(rawPrice));

        // Assert that the returned price is the transformed price (not raw)
        assertTrue(Fixed18.unwrap(v.price) == Fixed18.unwrap(expected));
    }
}

