        vm.assume(oracleAddr != address(0));
        vm.assume(oracleAddr != address(c));
        vm.assume(rawPrice != 0);

        // Deploy a minimal oracle that returns a fixed price
        MockOracle oracle = new MockOracle(rawPrice);
        vm.etch(oracleAddr, address(oracle).code);

        // Construct a payoff definition with type 0 (Passthrough) and direction 0 (NONE)
        // Passthrough transform: returns price unchanged; thus invariant trivially holds if bug is elsewhere.
        // Use a non-trivial transform: type = 1 (Linear), direction = 0, data encoding a multiplier (1e18 = 1.0)
        // Actually to make transform differ from identity, use a multiplier != 1e18 in data.
        // PayoffType.LINEAR = 1, PayoffDirection.NONE = 0
        uint8 payoffType = 1; // LINEAR
        uint8 payoffDirection = 0; // NONE
        // encode multiplier as int256 in data (stored in bytes30, big-endian)
        int256 multiplier = int256(1e18) + 1; // not identity
        bytes memory encoded = abi.encode(multiplier);
        // pad to 30 bytes
        bytes30 data30;
        assembly {
            mstore(add(data30, 0x20), mload(add(encoded, 0x20)))
        }
        PayoffDefinition memory def = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType(payoffType),
            payoffDirection: PayoffDefinitionLib.PayoffDirection(payoffDirection),
            data: data30
        });

        // Initialize C with the oracle and payoff def
        // But initialize requires being called once by controller? It's initializer(1) so anyone can call once.
        // We need to mock the controller? Actually C's initialize calls __UControllerProvider__initialize which checks
        // msg.sender is a contract (IController). So we need a minimal controller.
        // Deploy a minimal controller
        MockController controller = new MockController();
        // Set up controller's productBeacon etc? Not needed for initialization, only isContract check.
        vm.prank(address(controller));
        c.initialize(IProduct.ProductInfo({
            name: "test",
            symbol: "TEST",
            payoffDefinition: def,
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
