// Minimal oracle that just stores a price per version and returns it.
contract SimpleOracle {
    using Fixed18Lib for Fixed18;

    struct OracleVersion {
        uint256 version;
        uint256 timestamp;
        Fixed18 price;
    }

    uint256 public currentVersion;
    Fixed18 public currentPrice;

    mapping(uint256 => Fixed18) public prices;

    function setPrice(int256 rawPrice) external {
        currentPrice = Fixed18.wrap(rawPrice);
    }

    function sync() external returns (OracleVersion memory) {
        currentVersion++;
        prices[currentVersion] = currentPrice;
        OracleVersion memory v = OracleVersion({
            version: currentVersion,
            timestamp: block.timestamp,
            price: currentPrice
        });
        return v;
    }

    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion({
            version: currentVersion,
            timestamp: 0,
            price: prices[currentVersion]
        });
    }

    function atVersion(uint256 version) external view returns (OracleVersion memory) {
        require(version > 0 && version <= currentVersion, "Invalid version");
        return OracleVersion({
            version: version,
            timestamp: 0,
            price: prices[version]
        });
    }
}

