    function currentVersion() external view returns (OracleVersion memory);
    function atVersion(uint256 oracleVersion) external view returns (OracleVersion memory);
}

// Stub types (actual contracts use complex libraries; the test only needs the types to compile).
type Fixed18 is int256;
type UFixed18 is uint256;
type PackedFixed18 is int128;
type PackedUFixed18 is uint128;

library Fixed18Lib {
    function wrap(int256 a) internal pure returns (Fixed18) { return Fixed18.wrap(a); }
    function unwrap(Fixed18 a) internal pure returns (int256) { return Fixed18.unwrap(a); }
    function neg(Fixed18 a) internal pure returns (Fixed18) { return Fixed18.wrap(-Fixed18.unwrap(a)); }
    function isZero(Fixed18 a) internal pure returns (bool) { return Fixed18.unwrap(a) == 0; }
    function from(int256 a) internal pure returns (Fixed18) { return wrap(a); }
    function div(Fixed18 a, Fixed18 b) internal pure returns (Fixed18) { return wrap(unwrap(a) / unwrap(b)); }
    function abs(Fixed18 a) internal pure returns (UFixed18) {
        int256 v = unwrap(a);
        return UFixed18.wrap(uint256(v >= 0 ? v : -v));
    }
}

library UFixed18Lib {
    function wrap(uint256 a) internal pure returns (UFixed18) { return UFixed18.wrap(a); }
    function unwrap(UFixed18 a) internal pure returns (uint256) { return UFixed18.unwrap(a); }
    function mul(UFixed18 a, UFixed18 b) internal pure returns (UFixed18) { return wrap(unwrap(a) * unwrap(b) / 1e18); }
    function abs(UFixed18 a) internal pure returns (UFixed18) { return a; }
    function gt(UFixed18 a, UFixed18 b) internal pure returns (bool) { return unwrap(a) > unwrap(b); }
    function gte(UFixed18 a, UFixed18 b) internal pure returns (bool) { return unwrap(a) >= unwrap(b); }
    function lt(UFixed18 a, UFixed18 b) internal pure returns (bool) { return unwrap(a) < unwrap(b); }
    function lte(UFixed18 a, UFixed18 b) internal pure returns (bool) { return unwrap(a) <= unwrap(b); }
}

library PayoffDefinitionLib {
    enum PayoffType { PASSTHROUGH }
    enum PayoffDirection { LONG, SHORT }

    function valid(C.PayoffDefinition memory) internal pure returns (bool) { return true; }

    function transform(C.PayoffDefinition memory self, Fixed18 price) internal pure returns (Fixed18) {
        if (self.payoffType == PayoffType.PASSTHROUGH) {
            if (self.payoffDirection == PayoffDirection.LONG) return price.neg();
            else return price;
        }
        return price;
    }
}

library JumpRateUtilizationCurveLib {
    function compute(JumpRateUtilizationCurve memory, UFixed18) internal pure returns (Fixed18) { return Fixed18.wrap(0); }
}

struct JumpRateUtilizationCurve {
    PackedFixed18 minRate;
    PackedFixed18 maxRate;
    PackedFixed18 targetRate;
    PackedUFixed18 targetUtilization;
}

