contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address owner, address nonOwner) public {
        vm.assume(owner != address(0));
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != owner);

        // Initialize the contract with a valid product so that controller is set.
        IProduct.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "TEST";
        info.oracle = IOracleProvider(address(0)); // will revert on sync, but we only test the view
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        // The constructor sets the deployer as the owner of coordinator 0.
        // We need the controller to be an address with code. We deploy a minimal
        // IController that returns the owner we want.
        ControllerStub controllerStub = new ControllerStub(owner);
        vm.prank(owner);
        c.initialize(info);

        // We are only testing the controller() view function.
        // For the owner, it must not revert (returns controller address).
        // For a non-owner, the mutant adds onlyOwner(0) which reverts.
        bool ownerSuccess = false;
        bool nonOwnerSuccess = false;

        vm.prank(owner);
        try c.controller() returns (IController res) { ownerSuccess = true; } catch { ownerSuccess = false; }

        vm.prank(nonOwner);
        try c.controller() returns (IController res) { nonOwnerSuccess = true; } catch { nonOwnerSuccess = false; }

        // The correct contract returns successfully for both (no revert),
        // the mutant reverts for non-owner.
        assertTrue(ownerSuccess == nonOwnerSuccess);
    }
}

