// Minimal interfaces required for compilation.
interface IController {
    function isProduct(IProduct) external view returns (bool);
    function owner(uint256) external view returns (address);
    function owner() external view returns (address);
    function coordinatorFor(IProduct) external view returns (uint256);
    function collateral() external view returns (ICollateral);
    function incentivizer() external view returns (IIncentivizer);
    function minFundingFee() external view returns (UFixed18);
    function multiInvoker() external view returns (IMultiInvoker);
    function paused() external view returns (bool);
}

interface IProduct {
    function controller() external view returns (IController);
    function initialize(IProduct.ProductInfo calldata) external;
    struct ProductInfo {
        string name;
        string symbol;
        PayoffDefinition payoffDefinition;
        IOracleProvider oracle;
        UFixed18 maintenance;
        UFixed18 fundingFee;
        UFixed18 makerFee;
        UFixed18 takerFee;
        UFixed18 positionFee;
        UFixed18 makerLimit;
        JumpRateUtilizationCurve utilizationCurve;
    }
}

interface IOracleProvider {}

struct PayoffDefinition { bytes32 dummy; }
struct JumpRateUtilizationCurve {
    PackedFixed18 minRate;
    PackedFixed18 maxRate;
    PackedFixed18 targetRate;
    PackedUFixed18 targetUtilization;
}

type PackedFixed18 is int128;
type PackedUFixed18 is uint128;
type UFixed18 is uint256;
type ICollateral is address;
type IIncentivizer is address;
type IMultiInvoker is address;
